<?php
declare(strict_types=1);namespace Pam\Native\Widgets;use Closure;use InvalidArgumentException;use Pam\Native\Modules\NativeModuleResult;use Pam\Native\Modules\NativeModules;final class Widgets{public function update(string$identifier,WidgetContent$content,Closure$complete):int{if(preg_match('/^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$/D',$identifier)!==1)throw new InvalidArgumentException('Invalid widget identifier.');return NativeModules::call('widgets','update',['identifier'=>$identifier,...$content->payload()],static fn(NativeModuleResult$r)=>$complete($r->succeeded(),$r->succeeded()?null:$r->message()));}}
